Using ASCII values - O(n) Time and O(1) SpaceIterate through each character of the string and toggle its case using ASCII values: subtract 32 to convert lowercase to uppercase, and add 32 to convert uppercase to lowercase.
            C++

    #include <iostream>
using namespace std;

string toggleChar(string &str) {
    int ln = str.length();

    // Conversion according to ASCII values
    for (int i = 0; i < ln; i++) {
        if (str[i] >= 'a' && str[i] <= 'z')

            // Convert lowercase to uppercase
            str[i] = str[i] - 32;
        else if (str[i] >= 'A' && str[i] <= 'Z')

            // Convert uppercase to lowercase
            str[i] = str[i] + 32;
    }
    return str;
}

int main() {
    string str = "GeEkSfOrGeEkS";

    str = toggleChar(str);

    cout << str;
    return 0;
}


