    if (code >= 97 && code <= 122) {

      // Convert lowercase to uppercase (subtract 32)
      chars[i] = String.fromCharCode(code - 32);
    } else if (code >= 65 && code <= 90) {

      // Convert uppercase to lowercase (add 32)
      chars[i] = String.fromCharCode(code + 32);
    }
  }

  return chars.join('');
}

