            C++

    #include <iostream>
using namespace std;

string toggleChar(string S) {
    for (auto &ch : S) {

        // Toggle the 5th bit to flip case
        ch ^= (1 << 5);
    }
    return S;
}

int main() {
    string S = "GeEkSfOrGeEkS";
    cout << toggleChar(S);
    return 0;
}


